-- ============================================================================
-- HiWS — Hiswill Web Stack. The schema.
--
-- Create the database and load this file with:
--     mysql -uroot -proot -e "CREATE DATABASE IF NOT EXISTS hiws CHARACTER SET utf8mb4"
--     mysql -uroot -proot hiws < database.sql
--
-- WARNING: both tables are DROPped first, so importing this file destroys every
-- existing row. It is how the database is created from nothing, and how a
-- development copy is reset. It is not a migration and there is no runner.
--
-- The icon column holds a Font Awesome 6 name WITHOUT the style prefix, so
-- 'fa-screwdriver-wrench' renders as <i class="fa-solid fa-screwdriver-wrench">.
-- A value beginning 'fa-brands' is used as given, for brand marks.
--
-- The `bible` table is created empty: its 31,000 verses are text, not
-- schema, and live in database/bible.php. Load both with:
--     mysql -uroot -proot hiws < database.sql
--     php database/bible.php
-- ============================================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `bible`;
DROP TABLE IF EXISTS `tools`;
DROP TABLE IF EXISTS `projects`;

-- ----------------------------------------------------------------------------
-- projects — the cards on the home page. status = 0 hides a row without
-- deleting it, which is how a project still being built stays out of sight.
-- ----------------------------------------------------------------------------
CREATE TABLE `projects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` tinytext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `projects` VALUES (1,'Web Tools','A drawer of small online utilities for everyday jobs — domains, networking, security, colours, code and more. No sign-up, no cost.','tools','fa-screwdriver-wrench',1);
INSERT INTO `projects` VALUES (2,'Online Bible','Read the Bible online, anywhere, with nothing to install. Search a passage, open it by book and chapter, and read it on a clean, quiet page.','bible','fa-book-bible',1);
INSERT INTO `projects` VALUES (3,'Simple File Manager','A small web file manager: browse a folder, then upload, download, rename and delete, all from the browser. Handy when a phone is all you have.','sifm','fa-folder-tree',1);

-- ----------------------------------------------------------------------------
-- tools — every tool the tools project offers, with the explainer text that
-- sits under the form. `url` is the page name, so a row becomes /tools/<url>.
-- ----------------------------------------------------------------------------
CREATE TABLE `tools` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Untitled',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `url` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'question-circle',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Uncategorized',
  `status` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `title` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `tools` VALUES ('1','DNS Lookup','Ask a domain name for its DNS records — addresses, mail servers, name servers and more','','### About the DNS lookup\n\nType a domain name and the page asks your server\'s resolver for eight kinds of record: A, AAAA, CNAME, MX, NS, TXT, SOA and CAA. Every answer lands in one row of a table — the type, the host it belongs to, its time to live in seconds, and the value.\n\n**What it\'s for** — Seeing where a name points, which servers take its mail, who serves its zone, or whether it publishes a policy like SPF. It is the first thing to try when a site will not load or a message bounces.\n\n**How to use it** — Put the name in *Domain name* and press *Look up*. A pasted web address is fine: the scheme and path are dropped before the query. A string that is not shaped like a domain gets a sentence saying so, and a name with no records of any kind says that rather than showing an empty table.\n\n**Example** — `example.com` came back with 10 records: two A, two AAAA, an MX, two NS, two TXT, and an SOA naming `elliott.ns.cloudflare.com` with serial 2418004112.','dns-lookup','fa-server','Network','1');
INSERT INTO `tools` VALUES ('2','IP Address Lookup','Find the country, city, network and time zone behind an IP address, or behind your own','','### About the IP address lookup\n\nGive it an IPv4 or IPv6 address and the page asks IP-API.com for the record behind it, then prints the fields that came back: continent, country and country code, region, district, city, postal code, latitude and longitude, time zone, currency, ISP, organisation, autonomous system, and whether the address looks like a proxy or VPN.\n\n**What it\'s for** — Working out roughly where a visitor is, who runs the address you are connected through, or whether an address belongs to a data centre rather than a home line.\n\n**How to use it** — Type an address in *IP address* and press *Look up*. Leave the box empty and it uses the address this server sees you at, shown under the box. Anything that is not an IP address is refused, and if the service is unhappy its own message is shown.\n\n**Inputs and outputs** — Rows the service leaves blank are dropped, so a short table means a thin record rather than a failure. `8.8.8.8` came back as North America, United States, region Virginia, city Ashburn, time zone America/New_York, ISP Google LLC, organisation Google Public DNS, and autonomous system AS15169 Google LLC.\n\n**Good to know** — The answer is a live reply from a free service, so it depends on that service answering; the page credits it beneath the table.','ip-lookup','fa-network-wired','Network','1');
INSERT INTO `tools` VALUES ('3','WHOIS Lookup','Find who registered a domain name or IP address, and when the registration runs out','','### About the WHOIS lookup\n\nAsk about a domain name or an IP address and the page follows the protocol\'s own two-step route. It first questions whois.iana.org about the ending (or the address block), takes the referral out of that answer, then puts the same question to the registry the referral names. The record comes back as plain text, kept exactly as the registry wrote it apart from the comment lines that carry nothing.\n\n**What it\'s for** — Checking who holds a name, when it was created and when it expires, which company manages it, and which name servers answer for it.\n\n**How to use it** — Enter the name or address in *Domain name or IP address* and press *Look up*. A pasted web address is fine. The line above the record names the server that answered, which for a `.com` is usually the registry itself.\n\n**Example** — `example.com` was answered by `whois.verisign-grs.com` with a creation date of 1995-08-14, expiry 2027-08-13, the registrar recorded as RESERVED-Internet Assigned Numbers Authority, and name servers ELLIOTT.NS.CLOUDFLARE.COM and HERA.NS.CLOUDFLARE.COM.\n\n**Good to know** — Registrars redact contact details in many countries, so a missing address or email is normal. A busy registry returns nothing, and the page says to try again.','whois','fa-address-card','Network','1');
INSERT INTO `tools` VALUES ('4','Phone Lookup','Read a phone number\'s country, line type and international formats from its numbering plan','','### About the phone lookup\n\nA phone number is more than digits: its country calling code says where it belongs, and the national number that follows is laid out by rules each country sets. This tool reads those rules from Google\'s libphonenumber — the same data Android uses to dial — so it works for numbers anywhere in the world without anyone being rung.\n\n**What it\'s for** — Turning a locally written number into a clean international form, or checking whether a line is a mobile, a fixed line, toll free or premium rate before you dial it.\n\n**How to use it** — Type the number in *Phone number* and press *Look up*. A number starting with `+` carries its own country; one written the local way needs *Country it was written in* chosen from the list. With neither, the page asks for the code at the front.\n\n**Inputs and outputs** — You get the country, the calling code, the national number, the kind of line, and the same number written as E.164, *International*, *National* and *Dial from a phone*. A number that does not fit its country is refused in those words.\n\n**Example** — `+256 772 123456` came back as Uganda, country code +256, number 772123456, kind *Mobile*, E.164 `+256772123456`, national `0772 123456`.\n\n**Good to know** — It reads a number; it cannot tell you whose it is.','phone-lookup','fa-phone','Miscellaneous','1');
INSERT INTO `tools` VALUES ('5','Word Lookup','Look up an English word — its parts of speech, senses and example sentences','','### About the word lookup\n\nAsk for a word and the page fetches its entry from Wiktionary\'s definition API, which returns the English senses already sorted by part of speech. Each part of speech becomes its own card: a badge naming it, then the senses numbered, with example sentences in italics under the senses that carry them.\n\n**What it\'s for** — Checking a meaning while you write, seeing how many senses a word has, or borrowing an example sentence that already reads well.\n\n**How to use it** — Type the word in *Word* and press *Look up*. There is one card per part of speech, so `run` brings back its verb and noun entries together. Input outside letters, apostrophes, spaces and hyphens, or longer than 60 characters, is refused with *Enter a single word.*\n\n**Inputs and outputs** — A word with no English entry says so and suggests checking the spelling or trying the plural. Definitions come back as plain text, each with the examples it carries listed beneath it.\n\n**Example** — `serendipity` returns one *Noun* card with three senses, the first being the phenomenon of making an unplanned, fortunate discovery through a combination of unexpected circumstances.\n\n**Good to know** — The definitions come from Wiktionary, and a link under the result takes you to the full entry.','word-lookup','fa-book','Miscellaneous','1');
INSERT INTO `tools` VALUES ('6','Currency Converter','Convert an amount between two of 161 currencies at the day\'s reference rates','','### Converting money between currencies\n\n**What it\'s for** — Prices, budgets and invoices turn up in one currency and need to be in another. This takes the day\'s rate for the pair you pick and does the multiplication for you.\n\n**How to use it** — Enter an *Amount*, choose the *From* and *To* currencies from the two dropdowns — each entry reads as a code and a name, `USD — United States Dollar` — and press *Convert*. An empty amount counts as 1.\n\n**Inputs and outputs** — The answer card shows the amount, then the converted total in large type, then the rate used and the date the feed was updated: `1 USD = 129.8716 KES`, rates of Thu, 05 Nov 2026 00:02:31 +0000. An amount of zero or less, or one currency left unchosen, gets a message instead; if the feed does not answer, it says so and asks you to try again.\n\n**Example** — 100 USD to KES came back 12,987.16 KES at 1 USD = 129.8716 KES.\n\n**Good to know** — Rates come from ExchangeRate-API and are a daily reference, not a dealing price.','currencies','fa-dollar-sign','Calculation','1');
INSERT INTO `tools` VALUES ('8','Source Code Viewer','Fetch any public web address and read the raw HTML the server sends back','','### About the source code viewer\n\n**What it\'s for** — Every page is text sent by a server: markup, inline styles, script. Reading that text as it arrived shows how a page is put together, what a framework emits for a simple page, and what a site ships before the browser tidies it up.\n\n**How to use it** — Put a full address in *Web address*, starting with `http://` or `https://`, then press *View source*. Redirects are followed, so you read the page you finally land on.\n\n**Inputs and outputs** — Only public addresses are allowed; a local or private host is refused with a warning that it cannot be fetched. A working fetch gives a byte count, a line count and the address, then the whole response in a scrolling window. If nothing comes back — the site is down, or it refuses this server — you are told that in words rather than shown an empty box.\n\n**Example** — `https://example.com/` came back as 577 bytes over 2 lines, printed exactly as sent, with no highlighting or reformatting.','source-code','fa-code','Programming','1');
INSERT INTO `tools` VALUES ('9','Hash Generator','Turn a piece of text into MD5, SHA-1, SHA-2, SHA-3, RIPEMD-160, CRC32 and xxHash digests at once','','### About the hash generator\n\n**What it\'s for** — A hash turns text into a fixed-length fingerprint: the same input always gives the same output, and the text cannot be read back out of it. Use one to check a download against a published checksum, to store a password, or to give a string a stable identifier.\n\n**How to use it** — Type or paste into *Text to hash* and press *Generate hashes*. Every algorithm this server offers is computed at the same time: md5, sha1, sha224, sha256, sha384, sha512, sha3-256, sha3-512, ripemd160, crc32b and xxh128.\n\n**Inputs and outputs** — The answer is a table with one row per algorithm and a copy button beside each digest. Nothing is rejected, so an empty box simply hashes the empty string.\n\n**Example** — `Hello world` gives md5 `3e25960a79dbc69b674cd4ec67a72c62` and sha256 `64ec88ca00b268e5ba1a35678a1b5316d212f4f366b2477232534a8aeca37f3c`.','hash','fa-fingerprint','Security','1');
INSERT INTO `tools` VALUES ('10','SSL Checker','Read a site\'s TLS certificate from port 443: who signed it, what it covers and when it runs out','','### Reading a certificate from port 443\n\n**What it\'s for** — When a browser warns that a connection is not private, this shows what the server is actually presenting: who signed the certificate, which names it covers, and how long it has left. Verification is switched off on purpose, so a self-signed or otherwise broken certificate still reads.\n\n**How to use it** — Enter a *Host name* such as `example.com` and press *Check*. The page opens a secure connection to that host on port 443, the port HTTPS uses, and parses whatever comes back.\n\n**Inputs and outputs** — A host name needs at least one dot; anything else gets *That does not look like a host name*. A host that will not answer on 443 says it may not serve HTTPS at all. Otherwise a banner reads *Valid*, *About to expire* within 21 days, or *Expired*, with the days left or overdue, followed by a table of host, resolved address, issuer, validity dates, serial number, SHA-1 fingerprint, signature and alternate names.\n\n**Example** — `hiws.dev` reported *Valid — 81 days left of 89*, valid from 28 October 2026 to 26 January 2027, covering `hiws.dev` and `*.hiws.dev` with an ecdsa-with-SHA384 signature.','ssl-check','fa-shield-halved','Security','1');
INSERT INTO `tools` VALUES ('18','URL Shortener','Hand a long web address to a free shortening service and get a short link back','','### About the URL shortener\n\n**What it\'s for** — A long address with folders and query strings is awkward to send in a message or read out loud. A short link stands in for it and points at the same page.\n\n**How to use it** — Paste the whole address, `https://` included, into *Long address* and press *Shorten*. The tool asks three free services in turn — is.gd, then v.gd, then TinyURL — and the first one that answers with a link wins.\n\n**Inputs and outputs** — The address has to be a valid URL, or you are told to include the `https://` at the front. A success gives the short link, a *Copy* button, and the original underneath. If every service stays quiet, the page reports that none of them answered and suggests trying again in a moment.\n\n**Example** — `https://example.com/a/very/long/path?with=queries` came back as `https://is.gd/XW008D`.\n\n**Good to know** — The link belongs to the shortener rather than this site, and it keeps whatever expiry that service gives it.','short-url','fa-link','Programming','1');
INSERT INTO `tools` VALUES ('20','HEX to RGB Converter','Break a hex colour such as #7C3AED into its red, green and blue channels','','### About the hex to RGB converter\n\nTurns a hex colour code into the three decimal channels behind it, with a swatch of the colour so you can see what you typed.\n\n**What it\'s for** — Stylesheets, design tools and colour pickers hand you hex; image editors and many APIs speak in red, green and blue. Moving a colour between those two is a sum you should not have to do in your head.\n\n**How to use it** — Type into the *Hex colour* box: the `#` already stands in front of the field, so `7C3AED` and `#7C3AED` both work, and three-digit shorthand is read as each digit standing for itself twice. Press *Convert*.\n\n**Inputs and outputs** — Six hex digits or three, letters in either case. Anything else comes back as \"Enter a hex colour such as #7C3AED, or the shorthand #7C3.\" A good answer shows the swatch, `rgb(124, 58, 237)` beside a *Copy* button, and a table of Red, Green, Blue and the Hex they came from.\n\n**Example** — `7C3AED` gives `rgb(124, 58, 237)`, with Red 124, Green 58 and Blue 237.','hex-to-rgb','fa-palette','Conversion','1');
INSERT INTO `tools` VALUES ('21','RGB to HEX Converter','Turn three RGB values like 124,58,237 into the hex colour a stylesheet wants','','### About the RGB to hex converter\n\nTakes three red, green and blue values and writes them as the six-digit hex code a stylesheet wants.\n\n**What it\'s for** — Colour pickers and image editors show a colour as numbers from 0 to 255, while CSS, design tokens and brand guides are written as hex. This turns the triple you copied into the code you can paste.\n\n**How to use it** — Everything goes in the single *RGB colour* box, then *Convert*. All three of `255,255,255`, `(255,255,255)` and `rgb(255,255,255)` are accepted, so a value copied out of a stylesheet lands without editing.\n\n**Inputs and outputs** — Exactly three numbers, each between 0 and 255. A different count gives \"Enter three values, such as 255,255,255 or rgb(255,255,255).\"; one over 255 gives \"Each value has to be between 0 and 255.\" A good answer shows a swatch and `#7C3AED` in capitals, with a *Copy* button that puts the same code in lowercase on the clipboard.\n\n**Example** — `rgb(124,58,237)` comes back as `#7C3AED`.','rgb-to-hex','fa-swatchbook','Conversion','1');
INSERT INTO `tools` VALUES ('22','Code to Text ratio','Fetch a page and split its weight into the text a reader sees and the code that carries it','','### About the code to text ratio\n\nDownloads the page at an address you type in and weighs what comes back: how much of it is words a reader actually sees, and how much is markup, scripts and styling holding those words up.\n\n**What it\'s for** — A quick look at whether a page leans on prose or on machinery. A hand-written article sits light on code; a page assembled from components, embedded styles and scripts comes out the other way. Treat the figure as a description of the page, not a target to hit.\n\n**How to use it** — Paste a full `http://` or `https://` address into *Web address* and press *Calculate*. The tool fetches the page, drops every script and style block first, then squeezes what is left into plain text and splits the difference.\n\n**Inputs and outputs** — The address has to be public: a local host, a private network address or anything that is not http(s) comes back as *That address cannot be fetched.* If the site is down or refuses the request, you get *Nothing came back from* and the address. Otherwise you get a bar with the text share, then *Page size*, *Text* and *Code* in bytes, each with its percentage.\n\n**Example** — `https://example.com/` weighs 577 bytes: 170 bytes of text (29.5%) against 407 bytes of code (70.5%).','code-text-ratio','fa-percent','SEO','1');
INSERT INTO `tools` VALUES ('23','SSL Generator','Make a self-signed certificate and private key for a hostname, valid for ten years','','### Making a self-signed certificate\n\n**What it\'s for** — A development server, an internal tool or a local test rig wants to speak HTTPS, and no certificate authority is going to vouch for `dev.example.com`. This makes a pair on the spot: a 2048-bit RSA key and a certificate signed by that same key, good for ten years.\n\n**How to use it** — Type the *Host name for the certificate* and press *Generate*. The name has to look like a host, with at least one dot, so `dev.example.com` passes while `localhost` is turned away.\n\n**Inputs and outputs** — Two cards come back, *Certificate* and *Private key*, each in a read-only box with a copy button and a download link — `dev.example.com.crt` and `dev.example.com.key`. Nothing is written to the server; the pair exists only while that page is open. If the machine cannot make a key, it says so.\n\n**Example** — `dev.example.com` yields a certificate under that name, dated 5 November 2026 to 1 November 2036, ready for a server\'s certificate and key directives.\n\n**Good to know** — A browser will still warn: nobody outside has vouched for it. The organisation name comes from this server\'s OpenSSL configuration, not from anything you type.','ssl-generator','fa-certificate','Security','1');
INSERT INTO `tools` VALUES ('30','Website Screenshot Generator','Take a live screenshot of any public web page and show it right in the browser','','### Taking a picture of a web page\n\n**What it\'s for** — A screenshot is the quickest way to show somebody what a page looks like without asking them to open it: a site you are building, a page that may change, or a rendering you want on record.\n\n**How to use it** — Enter the full *Web address*, `https://` included, and press *Take the shot*. The picture is drawn live by thum.io and fetched straight from them by your browser, so this server never handles it.\n\n**Inputs and outputs** — A still of the top of the page, about 1000 pixels across, appears in a card with the address underneath and an *Open the page* link beside it. It takes a few seconds to arrive. Anything that is not a full address gets *Enter a full address, including the https:// at the front.*\n\n**Example** — `https://example.com/` returned a picture of the top of that page, with a link back to it.\n\n**Good to know** — A page behind a login, or one that leans on heavy JavaScript, may come out incomplete — that is a limit of the service, not of your link.','website-screenshot','fa-camera','Miscellaneous','1');
INSERT INTO `tools` VALUES ('31','HTTP Headers Viewer','See the status line and every HTTP header a server sends back for an address','','### About the header viewer\n\n**What it\'s for** — Along with the page itself, a server sends the practical details: the status code, the content type, caching rules, cookies, who answered and when. This tool reads them back for you.\n\n**How to use it** — Enter a full `http://` or `https://` address under *Web address*, then press *View headers*. Redirects are followed, so the rows come from the final response rather than the hop in between.\n\n**Inputs and outputs** — A local or private address is refused with a warning. A working fetch gives the status line, a count of the headers, and a table of *Header* and *Value* pairs. If the site is unreachable, you get a notice instead of a table.\n\n**Example** — `https://example.com/` answered `HTTP/1.1 200 OK` with 11 headers, among them `Content-Type: text/html; charset=utf-8` and `Server: cloudflare`.','http-headers','fa-table-list','Programming','1');
INSERT INTO `tools` VALUES ('32','ROT13,18,47 Encoding and Decoding','Apply ROT13, ROT18 and ROT47 to text and read all three results at once','','### About ROT encoding\n\n**What it\'s for** — A rotation cipher slides each character a fixed distance along a set. It is enough to keep a spoiler or a puzzle answer out of a passing glance, though not enough to hide anything from someone who thinks to rotate it back.\n\n**How to use it** — Type or paste into *Text to encode or decode* and press *Convert*. There is no mode to pick: all three ciphers run together, each answer in its own card with a copy button beside it.\n\n**How the three differ** — ROT13 moves letters 13 places, so applying it twice returns the original. ROT18 does the same to letters and shifts digits by 5 as well. ROT47 rotates every printable ASCII character — letters, digits and symbols — 47 places along.\n\n**Example** — `Hello 2026!` comes out as `Uryyb 2026!` for ROT13, `Uryyb 7571!` for ROT18 and `w6==@ a_aeP` for ROT47. Feed any one of those results back through the same cipher and the text returns.','rot','fa-right-left','Programming','1');

-- ----------------------------------------------------------------------------
-- tools, second set. Same shape as the rows above: the icon is a bare Font
-- Awesome name and the category groups the tool on /tools. Network and SEO are
-- older groups that simply grew; Text, Time and Generator are new. The explainer
-- (info) opens with a heading, which becomes the summary the page folds away.
-- ----------------------------------------------------------------------------
INSERT INTO `tools` VALUES ('33','What Is My IP','See the address this site sees you at, with the details that travel with the request','what is my ip, my ip address, find my ip','### About this address\n\nThere is nothing to fill in: the page answers the moment it opens, because the address is the one your request arrived on. Alongside it sit the details the server can read from the request — whether the address is IPv4 or IPv6, the reverse name behind it when there is one, the port, whether the connection was HTTP or HTTPS, the host name the page was asked for, your browser\'s user agent, and the language it said it prefers.\n\n**What it\'s for** — Seeing what any website you visit can tell about your connection, and checking what a proxy or a VPN is putting in front of you. There is a *Refresh* link under the table to look again.\n\n**Inputs and outputs** — There are no inputs. Rows the server cannot fill in are simply left out, so a missing line means the detail was not sent rather than that something went wrong. A recent run showed the address 172.70.243.95, protocol IPv4, port 443, scheme HTTPS, host `tools.hiws.dev`, and `curl/8.5.0` as the user agent.\n\n**Good to know** — This is only what this server can see. If a proxy or a CDN sits in front of it, the address belongs to that, and a VPN or a mobile network will show something different again.','what-is-my-ip','fa-globe','Network','1');
INSERT INTO `tools` VALUES ('34','Reverse DNS Lookup','Ask an IP address which hostname the network gave it, through its reverse zone','reverse dns, ptr lookup, rdns, reverse ip','### About the reverse lookup\n\nA normal lookup turns a name into an address; this one goes the other way. Give it an IP address and the page asks what name the network gave that address — first with a plain reverse lookup, then by querying the PTR records of the matching reverse zone. Give it a hostname instead and it resolves that to an IPv4 address first, so both inputs end up asking the same question.\n\n**What it\'s for** — Checking whether an address belongs to a named host. It is the kind of housekeeping a mail server does before it decides to trust a sender.\n\n**How to use it** — Type an address or a name in *IP address or hostname* and press *Look up*. The answer lists the address it settled on, any hostname it found, the reverse zone it queried, and how many PTR records came back.\n\n**Example** — `8.8.8.8` came back as `dns.google`, from the zone `8.8.8.8.in-addr.arpa`, with one PTR record.\n\n**Good to know** — Plenty of addresses have no reverse record at all. The page then says so in place of a count rather than failing, and a name that will not resolve to an IPv4 address gets a sentence asking you to check the spelling.','reverse-dns','fa-retweet','Network','1');
INSERT INTO `tools` VALUES ('35','IPv4 Subnet Calculator','Work out the network, broadcast, mask and usable hosts of an IPv4 CIDR block','subnet calculator, cidr, netmask, ipv4, network address','### About the subnet calculator\n\nAn IPv4 address is really two things: a network, and a host inside it, split wherever the mask falls. Give this tool an address and a prefix length — the `/24` at the end of a CIDR block — and it prints the boundaries that split defines.\n\n**What it\'s for** — Working out which range a block covers, whether two addresses can talk to each other directly without a router, and how many devices will fit inside it.\n\n**How to use it** — Fill *IPv4 address* and *Prefix* (the slash is already drawn in front of that box), then press *Calculate*. Both boxes have defaults, so an empty form still works: 192.168.1.10 with prefix 24.\n\n**Inputs and outputs** — IPv4 only, and the prefix has to be a whole number from 0 to 32; anything else gets a short sentence saying so. You get the netmask and wildcard, the network and broadcast addresses, the first and last usable host, the total address count and the usable host count. A /31 or /32 has no usable hosts, and the page says that instead of leaving a blank.\n\n**Example** — 192.168.1.10 with prefix 24 gives netmask 255.255.255.0, wildcard 0.0.0.255, network 192.168.1.0/24, broadcast 192.168.1.255, first host 192.168.1.1, last host 192.168.1.254, 256 addresses and 254 usable hosts.','subnet-calculator','fa-sitemap','Network','1');
INSERT INTO `tools` VALUES ('36','Email Checker','Check an email address\'s shape and whether its domain publishes mail servers','email checker, email validator, mx record, verify email','### About the email checker\n\nTwo separate questions, in order: does the address look like an address, and does the domain after the at-sign accept mail? The first is a syntax rule checked on the spot; the second is a live DNS question about the domain\'s MX records.\n\n**What it\'s for** — Catching a typo before you send, or checking a domain you are about to sign up with. It says nothing about the mailbox itself: only the mail server knows whether a particular name exists, and it will not say.\n\n**How to use it** — Type the address in *Email address* and press *Check*. The result lists the address, the domain, the syntax verdict, the mail servers found, whether the domain also has an A record, and a plain-English answer to whether it can receive.\n\n**Inputs and outputs** — An empty box or a string without an at-sign gets a short refusal. When mail servers are found they are listed by name. If the domain has neither mail servers nor an address record the verdict reads *No — the domain has no mail or address record*, and a domain with an address record but no MX reads *Unclear*.\n\n**Example** — `someone@gmail.com` passed the syntax check and returned five Google mail servers, an A record, and *Yes — the domain publishes mail servers*.','email-checker','fa-envelope-circle-check','Network','1');
INSERT INTO `tools` VALUES ('37','HTTP Status Checker','Ask a web address what it answers with — status, redirects, headers and time','http status, status code, check website, http response, redirect','### About the status checker\n\nEvery answer a web server gives starts with a three-digit code: 200 for a good page, 301 for a permanent move, 404 for a page that is not there, 500 for a server that fell over. Put an address in and this page fetches it, follows any redirects, and reports what came back.\n\n**What it\'s for** — Checking that a page is live, seeing where an old link now points, or finding out which server and content type a site answers with.\n\n**How to use it** — Enter a *Web address* and press *Check*. A bare domain is enough: `example.com` is tried as `https://example.com`. Only public http and https addresses are fetched, so a private or malformed one is turned away with a sentence saying so, and an address that never answers says that instead.\n\n**Inputs and outputs** — The answer gives the URL as fetched, the status line, how many redirects were followed, and the Server, Content type, Content length, Location, Powered by and Cache control headers when the server sent them, plus the time in milliseconds.\n\n**Example** — `example.com` answered 200 OK with no redirects, server `cloudflare`, content type `text/html; charset=utf-8`, in 118 ms.','http-status','fa-signal','Network','1');
INSERT INTO `tools` VALUES ('38','Port Checker','See whether a host has a particular port open, and what service answers on it','port check, open port, port scanner, tcp port','### About the port check\n\nA server offers its services on numbered ports — 22 for SSH, 80 for the web, 443 for secure web. This tool opens one connection to a single host and port, waits up to five seconds, and reports whether anything accepted it.\n\n**What it\'s for** — Confirming that a service is reachable from outside, that a firewall rule took effect, or that the port you are about to open really is answering.\n\n**How to use it** — Enter the *Host* (a name or an address) and the *Port*, then press *Check port*. Well-known ports come back with a name beside the number: 443 reads *HTTPS*, 22 reads *SSH*, and anything the list does not cover says *Unlabelled port*.\n\n**Inputs and outputs** — The port must be a number from 1 to 65535, and the host must resolve to a public address. Private and reserved ranges are refused, so the page cannot be used to poke at this server\'s own network. You get the resolved address when a name was typed, the service name, the state, and the time in milliseconds.\n\n**Example** — `example.com` on port 443 resolved to 172.66.147.243, service *HTTPS*, state *Open — something accepted the connection*, in 2 ms. A port with nothing listening reads *Closed, or filtered by a firewall*.','port-check','fa-plug','Network','1');
INSERT INTO `tools` VALUES ('39','Base64 Encoder & Decoder','Encode text as Base64, or decode Base64 back into the text it stands for','base64, encode, decode, base64 converter','### About the Base64 encoder\n\n**What it\'s for** — Base64 rewrites bytes using 64 printable characters, so data that a plain text channel cannot carry — a token in a URL, an image inside a stylesheet — survives the trip. It hides nothing, since anyone can turn it back: it is an encoding, never encryption.\n\n**How to use it** — Set *Direction* to *Encode text* or *Decode Base64*, type into *Input*, then press *Convert*.\n\n**Inputs and outputs** — Encoding accepts any text at all. Decoding strips line breaks first — a wrapped block arrives with them — and then checks what is left, so a stray character brings the message that it is not valid Base64. An empty box simply asks you to enter some text. The answer lands in a card labelled *Base64* or *Decoded text*, with a copy button.\n\n**Example** — `HiWS rocks` encodes to `SGlXUyByb2Nrcw==`, and decoding that gives `HiWS rocks` again.','base64','fa-keyboard','Programming','1');
INSERT INTO `tools` VALUES ('40','URL Encoder & Decoder','Escape text into percent-encoded form so it can sit in a URL, or read it back','url encode, url decode, percent encoding, url encoding','### About URL encoding\n\n**What it\'s for** — A URL accepts only a small set of characters, so anything outside it — a space, a question mark, a non-Latin letter — is written as a percent sign and two hex digits. That is what lets a search term ride along in a query string without breaking the address.\n\n**How to use it** — Choose *Encode* or *Decode* in *Direction*, put the text in *Input*, then press *Convert*.\n\n**Inputs and outputs** — Encoding escapes the whole string, turning a space into `+` and anything else into `%xx` form. Decoding reads that form back, so `%26` becomes an ampersand and a `+` becomes a space. An empty box gets a notice asking for some text or a URL; a good run gives a card labelled *Encoded* or *Decoded* with a copy button.\n\n**Example** — `hello world & more` encodes to `hello+world+%26+more`, and decoding that returns the sentence you started with.','url-encode','fa-anchor','Programming','1');
INSERT INTO `tools` VALUES ('41','HTML Entity Encoder & Decoder','Turn characters such as a less-than sign into HTML entities, and turn them back','html encode, html decode, html entities, escape html','### About HTML entities\n\n**What it\'s for** — A few characters a browser would read as markup — a less-than sign, an ampersand, a double quote — have named and numeric entity forms. Encoding text with them lets a snippet be shown exactly as written instead of being parsed as markup.\n\n**How to use it** — Set *Direction* to *Encode* or *Decode*, paste into *Input*, then press *Convert*.\n\n**Inputs and outputs** — Encoding escapes both quote characters as well as the angle brackets, so the result is safe between tags and inside an attribute alike. Decoding turns named and numeric entities back into the characters they stand for. An empty box gets a notice asking for some text or markup; a good run gives a card labelled *Encoded entities* or *Decoded text* with a copy button.\n\n**Example** — `<p class=\"quote\">Tom & Jerry</p>` encodes to `&lt;p class=&quot;quote&quot;&gt;Tom &amp; Jerry&lt;/p&gt;`.','html-entities','fa-file-lines','Programming','1');
INSERT INTO `tools` VALUES ('42','JSON Formatter','Validate a block of JSON, say where it broke, and print it neatly indented','json formatter, json validator, prettify json, json beautifier','### About the JSON formatter\n\n**What it\'s for** — JSON usually arrives squashed onto one line, or arrives broken. This tool parses what you paste, tells you whether it holds together, and lays it out so a person can read it.\n\n**How to use it** — Paste into *JSON* and press *Format*.\n\n**Inputs and outputs** — Valid input gets a one-line summary — an object or a list, with the number of top-level keys or items — followed by the same data indented, slashes and non-Latin characters left unescaped so addresses stay readable. Broken input gets the parser\'s own message, such as *That is not valid JSON: Syntax error.*, and nothing else. An empty box asks you to paste some JSON.\n\n**Example** — `{\"name\":\"HiWS\",\"tags\":[\"tools\",\"free\"]}` comes back as *an object with 2 top-level keys*, then the same data printed over seven indented lines.','json-format','fa-file-code','Programming','1');
INSERT INTO `tools` VALUES ('43','Markdown to HTML','Convert Markdown into HTML, and see the same text rendered as a preview','markdown, markdown to html, md converter','### About Markdown to HTML\n\n**What it\'s for** — Markdown is the shorthand writers use for headings, emphasis, links and lists without writing a single tag. This tool runs it through a parser and hands back the HTML that text stands for, ready to paste into a page or a template.\n\n**How to use it** — Write or paste into *Markdown*, then press *Convert*.\n\n**Inputs and outputs** — You get two things: the HTML in a card labelled *HTML*, with a copy button, and a *Preview* box underneath showing the same markup rendered as a reader would see it. Raw tags typed into the input are escaped rather than obeyed, so script pasted in from elsewhere cannot run. Blank input gets a notice asking you to write some Markdown.\n\n**Example** — `# Heading` on one line and `Some *emphasis* and a [link](https://example.com).` on the next come back as `<h1>Heading</h1>` and a paragraph whose `a` tag points at that address; the preview shows the heading, the italic word and a live link.','markdown','fa-brands fa-markdown','Programming','1');
INSERT INTO `tools` VALUES ('44','CSS Minifier','Strip the comments and needless whitespace out of a stylesheet, and count the bytes saved','css minifier, minify css, compress css','### About the CSS minifier\n\n**What it\'s for** — A stylesheet is written for people: indentation, comments, spaces around the punctuation. A browser needs none of that, and a smaller file downloads faster without changing a single thing the page does.\n\n**How to use it** — Paste the stylesheet into *Stylesheet*, then press *Minify*.\n\n**Inputs and outputs** — The tool deletes `/* */` comments, collapses every run of whitespace to one space, pulls the spaces out around punctuation CSS does not need them for, and drops the last semicolon before a closing brace. You get three figures — *Original*, *Minified* and *Saved* as a percentage — then the result in a card labelled *Minified CSS* with a copy button. Blank input gets a notice asking for some CSS.\n\n**Example** — A commented five-line rule came out as `.card{color:red;margin:0 auto}`, falling from 56 B to 30 B — 46% saved.','css-minifier','fa-paint-roller','Programming','1');
INSERT INTO `tools` VALUES ('45','HTML Minifier','Collapse comments and runs of whitespace in a block of HTML, and count the saving','html minifier, minify html, compress html','### About the HTML minifier\n\n**What it\'s for** — HTML carries a lot that a browser throws away on arrival: comments, the blank lines that make a template readable. Trimming it cuts a page\'s weight without changing a thing about what renders.\n\n**How to use it** — Paste the markup into *HTML*, then press *Minify*.\n\n**Inputs and outputs** — The tool deletes comments — except the conditional `<!--[if ...]>` kind older markup still hides behind — joins the gap between adjacent tags, then collapses any run of two or more spaces to one. You are shown *Original*, *Minified* and *Saved* as a percentage, then the result in a card labelled *Minified HTML* with a copy button. Tags and attributes themselves are left exactly as written, and blank input gets a notice asking for some HTML.\n\n**Example** — A commented four-line `<div>` block came out as `<div class=\"card\"><p>Hello</p></div>` on one line, falling from 65 B to 36 B — 45% saved.','html-minifier','fa-compress','Programming','1');
INSERT INTO `tools` VALUES ('46','Password Generator','Build a strong random password from the length and the character sets you choose','password generator, strong password, random password','### Building a random password\n\n**What it\'s for** — Anything worth logging into deserves a password nobody can guess. This draws one from the system\'s cryptographic random source rather than a predictable sequence, so two runs never hand out the same string.\n\n**How to use it** — Set *Length*, then tick *Lowercase*, *Uppercase*, *Digits* and *Symbols* under *Include*, and press *Generate*. The starting point is 20 characters with lowercase, uppercase and digits ticked and symbols left off.\n\n**Inputs and outputs** — The password arrives in a labelled box with a copy button, and nothing here records it. The length must be a whole number from 4 to 128, at least one set has to be ticked, and the length must be big enough to hold one character of every set you chose — each refusal gets its own message. Whatever you pick, one character of each chosen set is guaranteed to appear.\n\n**Example** — Length 20 with all four sets ticked produced `DrmD7Un=gN9zu[87b$oh`. The look-alike characters `l`, `I`, `1`, `O` and `0` are kept out of the pools, so a password reads back cleanly off a screen.','password-generator','fa-key','Security','1');
INSERT INTO `tools` VALUES ('47','Password Strength Checker','Estimate a password\'s entropy and how long a guessing attack would take to crack it','password strength, password checker, how strong is my password','### Estimating how hard a password is to guess\n\n**What it\'s for** — A quick, honest read on a password before you commit to it: how big an alphabet it draws on, how much entropy that gives, and roughly how long an offline attack would take against it.\n\n**How to use it** — Type the password into *Password* and press *Measure*. It is checked on the page and never stored or sent anywhere. The field is a plain text box, so do not measure a real one over someone\'s shoulder.\n\n**Inputs and outputs** — You get a table of length in characters, the size of the alphabet, entropy in bits, the number of combinations, time to crack at a billion guesses a second, and a verdict: *Very weak*, *Weak*, *Reasonable*, *Strong* or *Very strong*. A bar under it fills to the entropy, and a line names any character type that is missing. An empty box simply asks you to type one.\n\n**Example** — `correction horse battery staple` measured 31 characters on a 59-character alphabet, 182 bits of entropy, *Very strong* — yet still 1.2 × 10^37 years at a billion guesses a second.','password-strength','fa-shield','Security','1');
INSERT INTO `tools` VALUES ('48','.htpasswd Generator','Write a username and hashed password for Apache\'s .htpasswd, with a matching .htaccess snippet','htpasswd, apache password, basic auth, htaccess password','### Writing a line for .htpasswd\n\n**What it\'s for** — Apache can ask for a username and password before it serves a directory: a staging area, a private folder, an admin page. The credentials live in a file called `.htpasswd`, one line per user, and this writes that line for you.\n\n**How to use it** — Fill in *Username* and *Password*, pick a *Hash* — bcrypt, the default and what Apache 2.4 reads directly, or SHA-1, the older form many shared hosts still expect — then press *Generate*.\n\n**Inputs and outputs** — Two boxes follow. The first is the line to append to `.htpasswd`; the second is a ready `.htaccess` snippet with `AuthType Basic`, `AuthName`, `AuthUserFile` and `Require valid-user`, where the file path is a placeholder you replace. Both carry copy buttons. A username outside letters, digits, `.`, `_`, `@` and `-`, or a blank field, is refused with a message.\n\n**Example** — Username `alice`, password `hunter2` on bcrypt gave `alice:$2y$10$zotveRhWT.QtYh.V0K8X0eIuD.aDW08cToLBEz9A5vGT5e9Z/YV3.` Each run salts it afresh, so the same pair will not repeat.','htpasswd','fa-user-lock','Security','1');
INSERT INTO `tools` VALUES ('49','Number Base Converter','See the same number in binary, octal, decimal and hexadecimal all at once','number base, binary to decimal, hex converter, radix','### About the number base converter\n\nRewrites one number in the four bases a person meets most — binary, octal, decimal and hexadecimal — from a single entry.\n\n**What it\'s for** — A stack dump, a bitmask, a colour code or an escape in a log each arrives in one base and has to be understood in another. Enter the number where it already lives and read the other three.\n\n**How to use it** — Type into *Number*, choose *It is written in* — Binary (2), Octal (8), Decimal (10) or Hexadecimal (16) — and press *Convert*. A `0x`, `0b` or `0o` prefix is taken as a hint and dropped before the digits are checked.\n\n**Inputs and outputs** — Digits have to belong to the base you picked: `FF` under Decimal (10) gives \"That is not a base-10 number.\", and an empty box gives \"Enter a number.\" The answer is four rows — Binary, Octal, Decimal and Hexadecimal — with the hexadecimal in capitals.\n\n**Example** — 255 under Decimal (10) gives Binary `11111111`, Octal `377`, Decimal `255` and Hexadecimal `FF`.','number-base','fa-hashtag','Conversion','1');
INSERT INTO `tools` VALUES ('50','Unit Converter','Convert between metres and feet, kilograms and pounds, Celsius and much more','unit converter, length, weight, temperature, measurement','### About the unit converter\n\nConverts an amount between two units of the same kind, then lists that one amount in every other unit of the kind.\n\n**What it\'s for** — Recipe volumes, road distances, file sizes, a thermostat set in the wrong scale. The two lists cover Length, Mass, Volume, Area, Speed, Data and Temperature — metres and feet, litres and gallons, bytes and kibibytes, Celsius, Fahrenheit and Kelvin.\n\n**How to use it** — Type an *Amount*, pick *From* and *To* under their group headings, press *Convert*. The page opens on 1 Metre (m) and Foot (ft).\n\n**Inputs and outputs** — Both units must belong to one group, so mixing them gives \"Those are different kinds of measurement — pick two of the same kind.\"; an amount that is not a number gives \"Enter a number to convert.\" The answer is a headline equation and a table of the same amount in every unit of that group, temperature included, where scale and offset both apply.\n\n**Example** — 1 Metre (m) = 3.28084 Foot (ft), with 100 in centimetres, 1000 in millimetres and 0.000621 in miles beside it.','unit-converter','fa-ruler-combined','Conversion','1');
INSERT INTO `tools` VALUES ('51','Text & Binary Converter','Turn text into the eight-bit groups that store it, and turn the bits back','text to binary, binary to text, binary converter','### About the text and binary converter\n\nEncodes text as eight-bit groups, and decodes those groups back into text, from one field with a direction selector.\n\n**What it\'s for** — Checking what a string looks like on the wire, unpacking a byte dump, or seeing how characters are stored at all. The *Direction* select offers *Text to binary* and *Binary to text*, so the same *Input* box serves both.\n\n**How to use it** — Choose the direction, type or paste into *Input*, press *Convert*. Encoding walks the text one byte at a time, so every character takes its own group of eight bits and a non-Latin letter takes the two or three it really occupies. Decoding drops everything that is not a 0 or a 1, spaces and line breaks included.\n\n**Inputs and outputs** — An empty box gives \"Enter some text or binary.\" Decoding needs whole groups of eight bits, or you get \"Binary has to be whole groups of eight bits. Spaces and line breaks are ignored.\" The answer sits in a card labelled *Binary* or *Text*, with a *Copy* button.\n\n**Example** — `Hello` encodes to `01001000 01100101 01101100 01101100 01101111`, and `01001000 01101001` decodes to `Hi`.','binary','fa-microchip','Conversion','1');
INSERT INTO `tools` VALUES ('52','Roman Numeral Converter','Convert between Roman numerals and ordinary numbers, whichever way you type','roman numerals, roman numeral converter, numeral','### About the Roman numeral converter\n\nWorks out which way round you are going: digits in give a numeral, letters in give a number.\n\n**What it\'s for** — Chapter numbers, clock faces, copyright lines and inscriptions are still cut in Roman numerals. Reading one off a page, or writing one for a title page, is a job you do in both directions.\n\n**How to use it** — Everything goes into the single *Number or Roman numeral* field, then *Convert*. The field decides from what you typed, as its own hint says: \"Digits go one way, letters the other — it works out which.\"\n\n**Inputs and outputs** — Digits have to fall between 1 and 3999, which is all the system can write; anything wider gets \"Roman numerals here cover 1 to 3999.\" Letters are checked for shape first, so `IIII` or `VX` is refused with \"That is not a Roman numeral — only I, V, X, L, C, D and M in their proper order.\" A good answer is a card labelled *Roman numeral* or *Number*, with a *Copy* button.\n\n**Example** — `1994` becomes `MCMXCIV`, and typing `MCMXCIV` gives back `1994`.','roman','fa-v','Conversion','1');
INSERT INTO `tools` VALUES ('53','Meta Tag Generator','Fill in a title and a description and get back the whole set of head tags that carry them','meta tags, meta tag generator, seo, open graph','### About the meta tag generator\n\nWrites the block of tags that goes into a page\'s head, so one title and one description come out already wired into every tag that needs them.\n\n**What it\'s for** — A search result shows a title and a summary line; a link shared on social media unfurls into a card with the same two lines and an image. Hand-typing that set invites missing tags and broken quotes. Fill the form once and paste the lot.\n\n**How to use it** — Only *Page title* is required — press *Generate* with it blank and you are told a title is the one tag worth having. *Description* fills both the search summary and the social card. *Canonical URL* adds a canonical link and an `og:url`, *Social image URL* adds the image tags and switches the Twitter card to `summary_large_image`, *Site name* adds `og:site_name`, and *Twitter handle* adds `twitter:site`.\n\n**Inputs and outputs** — You get *Search result, roughly*, a mock of how the link may look, above a copyable *Meta tags* box. Anything inside a value that would close the attribute early — a quote, an angle bracket — is removed or turned into an apostrophe.\n\n**Example** — Title `About HiWS` with a canonical URL of `https://hiws.dev/about` gives the title, description, viewport, `og:` and Twitter lines, then the canonical link.','meta-tags','fa-tags','SEO','1');
INSERT INTO `tools` VALUES ('54','Robots.txt Generator','Set out the paths a crawler may skip and the sitemap you want it to read, as a ready robots.txt','robots.txt, robots generator, crawl rules, seo','### About this robots.txt generator\n\nAssembles the small plain-text file that sits at a site\'s root and greets every arriving crawler: who the rules are for, which paths to stay out of, and where the sitemap is.\n\n**What it\'s for** — Keeping automated visitors off a staging area, an account page or an admin script while still handing search engines the address of your sitemap. A crawler treats the file as a request rather than a locked door, and the honest ones follow it to the letter.\n\n**How to use it** — Type a *User agent*; leave that blank and the output says `*`, which stands for every crawler. Paste a *Sitemap URL*, and list *Paths to keep out, one per line* — a path typed without a leading slash gets one added. Ticking *Let every crawler in — nothing to block* discards the path list and writes an empty `Disallow:` instead. Press *Generate*.\n\n**Inputs and outputs** — The answer arrives in a copyable *robots.txt* box, with a blank line separating the rules from the sitemap line when there is one. Save it as `robots.txt` at the top of your site.\n\n**Example** — Agent `Googlebot`, paths `/admin` and `/cart`, sitemap `https://example.com/sitemap.xml` gives four lines: the agent, two `Disallow:` rules, then the sitemap.','robots','fa-robot','SEO','1');
INSERT INTO `tools` VALUES ('55','Keyword Density Checker','See which words your text repeats, with a count and a share of the whole for each one','keyword density, word frequency, seo, keyword analysis','### About keyword density\n\nSplits a block of text into words, counts how often each one appears, and ranks them with the share of the total beside every entry.\n\n**What it\'s for** — Finding out what a draft is really about, catching a word you have leaned on too hard, and checking a page against the phrase you meant it to cover. It is a writing aid: search engines stopped rewarding repetition long ago, but the count still tells you where a piece drifts.\n\n**How to use it** — Paste the text into *Text* and press *Analyse*. The *Ignore common words* box strips out the connective filler — the, and, of, with — and is ticked on a fresh page, so the first table shows only words that carry meaning; untick it to count everything.\n\n**Inputs and outputs** — Empty input answers *Paste some text to analyse.* Otherwise you get *Words*, *Unique words*, *Distinct terms* and *Top word*, then at most 25 rows of *Word*, *Count* and *Density*, each with a bar. Text is lower-cased and split on punctuation first, so `Cat` and `cat` land in one row, while an apostrophe stays inside the word.\n\n**Example** — *The garden gate was open. The garden dog sat by the gate, and the cat watched the dog from the garden path.* is 22 words; with the box ticked, *garden* leads at 3 uses, 13.64%.','keyword-density','fa-magnifying-glass-chart','SEO','1');
INSERT INTO `tools` VALUES ('56','Slug Generator','Turn a page title into the lowercase address segment that belongs under your domain','slug generator, url slug, permalink, seo url','### About the slug generator\n\nTakes a title and returns the piece of an address that stands for it: lower-case, punctuation gone, the words divided by a hyphen.\n\n**What it\'s for** — Blog posts, documentation and any URL you would rather read than explain. A slug built from the title keeps an address meaningful long after its publication date, and it is the part of a result a person reads before clicking.\n\n**How to use it** — Type the title into *Title* and press *Make slug*. *Separator* switches the joins between *Hyphen (-)* and *Underscore (_)*. *Base URL* is optional: fill it in and a second box, *Full address*, appears with the slug appended to it.\n\n**Inputs and outputs** — Only the title is required; an empty one answers *Enter a title to turn into a slug.* Accented letters are folded to their plain forms first, so they survive in the slug instead of being dropped. Anything that is not a letter or a digit collapses into one separator, and the ends are trimmed.\n\n**Example** — `10 Ways to Speed Up Your Website` becomes `10-ways-to-speed-up-your-website`, and `Crème Brûlée Recipes` with the underscore separator plus a base of `https://example.com/blog` gives `https://example.com/blog/creme_brulee_recipes`.','slug','fa-tag','SEO','1');
INSERT INTO `tools` VALUES ('57','Reading Time Calculator','Estimate how long a piece of writing takes to read silently and to read aloud, with its counts','reading time, word count, reading speed, blog','### About the reading time estimate\n\nCounts the words in what you paste and turns them into a length of time: one figure for reading the text silently, a second for reading it out loud.\n\n**What it\'s for** — Putting an honest label on an article, chapter or talk so a reader knows whether it fits the next five minutes, and giving a speaker a rough run time for a script before anyone reaches a microphone.\n\n**How to use it** — Paste the writing into *Text* and press *Time it*. There is nothing else to choose; the rates are fixed at 200 words a minute for silent reading and 130 for reading aloud.\n\n**Inputs and outputs** — An empty box answers *Paste some text to time.* Otherwise the result opens with *Reading time* in large type and, under it, *to read, X aloud*, followed by a table of *Words*, *Characters*, *Sentences*, *Paragraphs* and both times. Anything under a minute reads in seconds; past that the clock turns to minutes and seconds. Tag markup is stripped before counting.\n\n**Example** — 116 words running to 619 characters in a single paragraph came back as 35 seconds to read and 54 seconds aloud, with 8 sentences and 1 paragraph counted alongside.','reading-time','fa-stopwatch','SEO','1');
INSERT INTO `tools` VALUES ('58','Percentage Calculator','Work out a percentage of a number, a share, a change, an increase or a decrease','percentage calculator, percent, percent change','### Five everyday percentage sums\n\n**What it\'s for** — Discounts, marks, growth figures and shares all reduce to a handful of shapes. Pick the shape you have and this does the arithmetic, then says the answer back in a sentence.\n\n**How to use it** — Choose the sum in *Work out*: *What is A% of B?*, *A is what percent of B?*, *Percentage change from A to B*, *Increase B by A%* or *Decrease B by A%*. Put a number in *First number (A)* and *Second number (B)*, then press *Calculate*. What A and B mean follows the label — in *Increase B by A%*, A is the percentage and B is the amount.\n\n**Inputs and outputs** — The result is the figure in large type with a sentence under it and a copy button beside it. Both boxes must hold a number, or you get *Put a number in each box*. Two sums also refuse a zero that would make the answer meaningless: a percentage of nothing, and a change measured from nothing.\n\n**Example** — On *What is A% of B?* with A = 15 and B = 200, the answer is 30 and the line reads *15% of 200 is 30.*','percentage','fa-divide','Calculation','1');
INSERT INTO `tools` VALUES ('59','BMI Calculator','Work out your body mass index and the healthy weight range for your height','bmi, body mass index, bmi calculator, health','### About the BMI calculator\n\nWorks out your body mass index — weight divided by height squared — from two numbers, and says which band it falls in.\n\n**What it\'s for** — BMI sorts adults into underweight, normal weight, overweight and obese. It is a rough public-health measure that ignores muscle, frame and age, so treat it as one clue rather than a diagnosis.\n\n**How to use it** — Pick the unit system you think in under *Units* — *Metric (kg, cm)* or *Imperial (lb, in)* — type your weight in *Weight* and your height in *Height*, then press *Calculate*. Imperial height is in inches: 5 ft 9 in is 69.\n\n**Inputs and outputs** — Both boxes need a number greater than zero, or the form asks for one. You get the BMI to one decimal place, the band it lands in, and the healthy weight range for your height in the unit you used.\n\n**Example** — 70 kg at 175 cm comes out at 22.9, in the *Normal weight* band.','bmi','fa-weight-scale','Calculation','1');
INSERT INTO `tools` VALUES ('60','Word & Character Counter','Count the words, characters, sentences, paragraphs and lines in any text you paste in','word counter, character counter, count words','### About the word counter\n\nCounts a pasted block of text seven ways at once, from raw characters up to the average length of a sentence.\n\n**What it\'s for** — Meeting a word limit, answering a form that asks for characters rather than words, or checking the shape of a draft before editing it. Every figure comes from the same input, so the whole picture arrives in one press.\n\n**How to use it** — Put the text into *Text* and press *Count*. The tool has no options: what you paste is what gets counted.\n\n**Inputs and outputs** — Empty input answers *Paste some text to count.* A word is a run of letters, digits, apostrophes and hyphens, so `well-known` and `don\'t` hold together as one word each, while any HTML tags are stripped out first. You get *Words*, *Characters*, *Characters without spaces*, *Sentences*, *Paragraphs*, *Lines* and *Average words a sentence*. Sentences are split on full stops, question marks and exclamation marks, and lines are counted as the newlines in your paste plus one.\n\n**Example** — `The cat sat. The dog ran!` gives 6 words, 25 characters, 20 without spaces, 2 sentences, 1 paragraph, 1 line, and 3.0 words a sentence.','word-counter','fa-spell-check','Text','1');
INSERT INTO `tools` VALUES ('61','Case Converter','Retype your text as upper, lower, title, sentence, camel, snake, kebab or constant case','case converter, uppercase, lowercase, title case','### About the case converter\n\nRewrites the words you give it in whichever style you pick, from a plain capitalisation fix to the naming conventions code expects.\n\n**What it\'s for** — Lowering a heading someone typed in shouting, tidying a run of names, or turning a phrase into an identifier that can sit in source without quotes. The joins between words come out of the text itself rather than from your keyboard.\n\n**How to use it** — Pick a *Style*, type into *Text*, press *Convert*. The choices are *UPPERCASE*, *lowercase*, *Title Case*, *Sentence case*, *camelCase*, *PascalCase*, *snake_case*, *kebab-case* and *CONSTANT_CASE*.\n\n**Inputs and outputs** — Empty input answers *Enter some text to convert.* The five joined styles split the text on punctuation and again wherever a lower-case letter or digit meets a capital, so `myVariableName` falls apart into three words before it is rebuilt. Everything else changes the case of your text as it stands. The answer sits in a copyable box named after the style you chose.\n\n**Example** — `Hello World example` as *Title Case* gives `Hello World Example` and as *CONSTANT_CASE* gives `HELLO_WORLD_EXAMPLE`; `my variable name` as *camelCase* gives `myVariableName`.','case-converter','fa-font','Text','1');
INSERT INTO `tools` VALUES ('62','Remove Line Breaks','Join the hard breaks in wrapped text back into flowing lines, tidy paragraphs, or a comma list','remove line breaks, join lines, unwrap text','### About removing line breaks\n\nPuts text that arrives wrapped at every column back into prose, deciding what should stand where the breaks were.\n\n**What it\'s for** — Copying out of a PDF, an email or a terminal, where each visual line ends with a break the sentence never intended. Joined back together, the text reads as writing again instead of a stack of half lines.\n\n**How to use it** — Choose a *Join as* style, paste into *Text*, press *Remove breaks*. *One line* turns every break into a space. *Keep paragraph breaks* joins inside a paragraph but leaves the blank lines that separate paragraphs. *Comma separated* puts a comma and a space where each break was, which suits a list of items lifted from a column.\n\n**Inputs and outputs** — Empty input answers *Paste some text with line breaks.* The answer appears in a copyable *Result* box, with the whitespace around each break folded away so no double spaces are left at the joins.\n\n**Example** — Text wrapped like this comes back as `The quick brown fox jumps over the lazy dog.`:\n\n```\nThe quick brown fox\njumps over the lazy\ndog.\n```','remove-line-breaks','fa-text-slash','Text','1');
INSERT INTO `tools` VALUES ('63','Lorem Ipsum Generator','Choose how many paragraphs, sentences or words of placeholder Latin to drop into your layout','lorem ipsum, placeholder text, dummy text','### About the lorem ipsum generator\n\nFills a layout with the usual scrambled Latin, so a design can be judged on its own terms before any real copy exists.\n\n**What it\'s for** — Mock-ups, wireframes and print proofs, where actual sentences would start a conversation about wording instead of spacing. The words are meaningless on purpose: the eye takes in the shape of the text, not its meaning.\n\n**How to use it** — Set *How many* to a whole number from 1 to 50, choose *Of what* — *Paragraphs*, *Sentences* or *Words* — and press *Generate*. The box *Start with \"Lorem ipsum dolor sit amet…\"*, ticked on a fresh page, puts that famous opening sentence in front of the output; a bare list of words never gets it.\n\n**Inputs and outputs** — An out-of-range number answers *Choose a whole number from 1 to 50.* Otherwise you get a copyable *Placeholder text* box: paragraphs separated by a blank line, sentences joined into one run, or a single line of words. Sentences run eight to fourteen words, each capitalised and closed with a full stop.\n\n**Example** — 3 words with the opening switched off came back as `Adipiscing ipsum mollit`.','lorem-ipsum','fa-paragraph','Text','1');
INSERT INTO `tools` VALUES ('64','Reverse Text','Run your text backwards by character, by whole word, or by line in one press','reverse text, backwards text, flip text','### About reversing text\n\nFlips what you paste three different ways, depending on whether the letters, the words or the lines should move.\n\n**What it\'s for** — Puzzles and ciphers, checking a value against its mirror image, or undoing a paste that came out backwards. It also makes the difference between a character and a word obvious: the same input, three readings of it.\n\n**How to use it** — Choose *Reverse* — *By character*, *By word* or *By line* — type into *Text*, press *Reverse*. *By character* turns every letter, space and mark around; *By word* keeps each word intact and reverses the order they appear in; *By line* does that to the lines of your text.\n\n**Inputs and outputs** — Empty input answers *Enter some text to reverse.* The result sits in a copyable box named after the mode you picked. Characters are read as characters rather than as bytes, so accented and other non-ASCII letters survive the turn intact.\n\n**Example** — `Hello World` by character gives `dlroW olleH`, while `one two three` by word gives `three two one`.','reverse-text','fa-shuffle','Text','1');
INSERT INTO `tools` VALUES ('65','Sort & Remove Duplicate Lines','Put a list into order and clear out duplicates and stray blank lines in a single pass','sort lines, remove duplicates, dedupe list, alphabetical sort','### About tidying a list\n\nTakes a list written one item to the line, puts it in order, and clears away the clutter on the way through.\n\n**What it\'s for** — A paste of names, links, domains or log lines that arrived unsorted and repeating themselves. Sorting gives the list a known shape, and dropping duplicates leaves one of each, which is usually the whole point.\n\n**How to use it** — Put the list into *Lines* and press *Tidy up*. *Sort* offers *A to Z*, *Z to A* and *Leave the order alone*. Four boxes sit beside it: *Remove duplicates*, *Ignore case*, *Trim spaces* and *Drop empty lines*. All four are ticked on a fresh page, and each does what its label says — with *Ignore case* ticked the comparison is case-blind, so `Apple` and `apple` are the same entry, and two matches must otherwise be letter for letter.\n\n**Inputs and outputs** — Empty input answers *Paste a list, one line to a row.* You then get *Lines in*, *Lines out* and *Removed*, above a copyable *Lines* box holding what survived.\n\n**Example** — Five lines in:\n\n```\npear\nApple\napple\nplum\n  pear\n```\n\ncome out as three: `Apple`, `pear`, `plum`.','sort-lines','fa-arrow-down-a-z','Text','1');
INSERT INTO `tools` VALUES ('66','Timestamp Converter','Turn a Unix timestamp into a readable date, or read a date back into one','timestamp converter, unix time, epoch converter, unix timestamp','### About the timestamp converter\n\nReads a bare Unix timestamp as a date, and a written date as a timestamp, showing both at once.\n\n**What it\'s for** — Logs, APIs and databases hand over a count of seconds with no calendar attached, while people read dates. Paste either into *Timestamp or date* and press *Convert*: a run of digits is taken as the timestamp, anything else is read as a date, so `1760000000` and `2026-10-15 14:30` both work.\n\n**Inputs and outputs** — The answer is six rows: Unix timestamp, ISO 8601 (UTC), RFC 2822, Date (UTC), Time (UTC) and From now, which reads how far that moment sits from the moment you pressed the button — \"just now\" when the gap is under a minute. An entry that reads as neither gets \"That is neither a timestamp nor a date I can read — try 2026-10-15 or 15 Oct 2026.\" Above the form, a *Right now* card carries the current timestamp with a *Copy* button.\n\n**Example** — `1760000000` gives `2025-10-09T08:53:20Z`, `Thu, 09 Oct 2025 08:53:20 +0000` and the date `Thu, 9 Oct 2025`.','timestamp','fa-clock','Time','1');
INSERT INTO `tools` VALUES ('67','Age Calculator','Work out someone\'s age in years, months and days as of any date you pick','age calculator, how old am i, date of birth, birthday','### About the age calculator\n\nCounts the years, months and days between a date of birth and a day you choose.\n\n**What it\'s for** — Ages are awkward to subtract: months come in different lengths and a leap day shifts things by one. This gives the answer the way a person would say it, with the totals behind it, for a birthday, a form, or an argument about who is older.\n\n**How to use it** — Pick the *Date of birth*, then *As of*, which opens on today; the note under it reads \"Leave as today to work out a current age.\" Press *Work it out*. Days are counted from midnight to midnight, so the hour on the birth date does not matter.\n\n**Inputs and outputs** — Five rows come back: *Age* in years, months and days, *Total days*, *Total weeks*, *Total months*, and *Next birthday* as days away. A birth date that does not read gets \"That date of birth does not read as a date.\", and an \"as of\" before it gets \"The \\\"as of\\\" date falls before the date of birth.\"\n\n**Example** — Born 2000-01-15, read as of 2026-11-05: 26 years, 9 months, 21 days — 9,791 days in all, next birthday 71 days away.','age','fa-cake-candles','Time','1');
INSERT INTO `tools` VALUES ('68','Date Difference Calculator','Count the days, working days and weeks between any two dates you enter','date difference, days between dates, date calculator','### About the date difference calculator\n\nCounts how far apart two dates are, in days and in the units a person thinks in.\n\n**What it\'s for** — Deadlines, project spans, time off, the age of anything: whenever you need the gap between two dates rather than a mental walk through the calendar. Type them in either order, because whichever came first becomes the start.\n\n**How to use it** — Fill *First date* and *Second date*, which open pre-filled with today and thirty days ahead, then press *Compare*.\n\n**Inputs and outputs** — An empty field gives \"Fill in both dates.\"; a value that reads as no date gives \"One of those does not read as a date.\" Otherwise seven rows come back: Days, Working days, Weekend days, Weeks, Months, Years and a Calendar breakdown of years, months and days. Working days are counted one by one, Monday to Friday, with a span past twenty thousand days estimated at five in seven.\n\n**Example** — 2026-01-01 to 2026-03-01 is 59 days: 42 working days, 17 weekend days, 8.4 weeks, and 0 years, 2 months, 0 days on the calendar.','date-diff','fa-calendar-days','Time','1');
INSERT INTO `tools` VALUES ('69','UUID Generator','Generate version 4 UUIDs, from one to a hundred, with a single press of the button','uuid generator, guid, unique id, uuid v4','### About the UUID generator\n\nProduces version 4 UUIDs — random identifiers in the familiar 8-4-4-4-12 shape — one to a hundred at a time.\n\n**What it\'s for** — Anything that needs an identifier nobody has to coordinate: session keys, file names, rows in a table where no natural key will do. Version 4 is the random flavour, so the values can be handed out without a list behind them.\n\n**How to use it** — Enter *How many* and press *Generate*. The box opens on 5, and any whole number from 1 to 100 is accepted; `0` or `101` gets \"Choose a whole number from 1 to 100.\"\n\n**Inputs and outputs** — The answer is a card labelled *UUID version 4*, holding one identifier per line with a *Copy* button that takes the whole list. Each value is sixteen bytes with the version and variant bits stamped into place, drawn from the system\'s cryptographic source, so nothing about them is predictable or repeated between runs.\n\n**Example** — Asking for 3 returns three lines, one of them `c032ef66-ebdf-4eb1-a2b6-91da495b88fb`.','uuid','fa-id-badge','Generator','1');
INSERT INTO `tools` VALUES ('70','Random Number Generator','Draw whole numbers from any range, with or without repeats, in a single roll','random number, rng, random picker, lottery numbers','### About the random number generator\n\nDraws whole numbers from a range you set, either free to repeat or with every value different.\n\n**What it\'s for** — Raffles, picking a team, shuffling test data, choosing a sample: any time you want a number handed over rather than worked out. The draws come from the system\'s cryptographic source instead of a seeded sequence, so the values carry no pattern you could predict.\n\n**How to use it** — Set *Lowest* and *Highest* — negatives are fine, and the ends are swapped if you type them the wrong way round — then *How many*, tick *No repeats* when every value must differ, and press *Roll*.\n\n**Inputs and outputs** — Both ends must be whole numbers, and *How many* runs from 1 to 1000. Wanting more different numbers than the range holds gets \"A range of 5 whole numbers cannot yield 9 different ones.\" The answer is a card labelled *Numbers*, sorted when *No repeats* is on and in draw order when it is off, with Range, Drawn and Unique rows beneath it.\n\n**Example** — Lowest 1, highest 100, five numbers, *No repeats* ticked: `9, 59, 70, 75, 97`.','random-number','fa-dice','Generator','1');

-- ----------------------------------------------------------------------------
-- bible -- one row per verse, per translation. `number` is the book's place in
-- the canon (1..66) and is what a passage is looked up by, so every translation
-- lines up on the same book numbers. `version` is a key in BIBLE_VERSIONS
-- (app/config.php) — 'KJV', the one the site publishes.
--
-- Left empty on purpose -- see the note at the top of this file.
-- ----------------------------------------------------------------------------
CREATE TABLE `bible` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `version` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `number` tinyint UNSIGNED NOT NULL,
  `book` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `chapter` smallint UNSIGNED NOT NULL,
  `verse` smallint UNSIGNED NOT NULL,
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `place` (`version`,`number`,`chapter`,`verse`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
